  showColumn(column: PeopleColumn, shown: boolean): void {
    const user = this.user() ?? '';
    this.hiddenColumns.update((all) => {
      const off = new Set(all.get(user));
      if (shown) off.delete(column);
      else off.add(column);
      return new Map(all).set(user, off);
